#!/usr/bin/env bash
# Exercise 08: during a rebase "ours" is the branch you rebase ONTO, "theirs" is your own commit.
EX_DIR=$(cd "$(dirname "$0")" && pwd)
source "$EX_DIR/../../scripts/lib.sh"
echo "Ćwiczenie 08-ours-theirs-w-rebase: przygotowanie piaskownicy"
new_sandbox

write resources/messages_pl.properties <<'EOF'
# Generated by TransTool. Do not edit by hand: changes are overwritten by the next export.
cart.empty=Twoj koszyk jest pusty
cart.total=Razem
checkout.pay=Zaplac
checkout.thanks=Dziekujemy za zakupy
greeting=Witaj
login.failed=Nieprawidlowy login lub haslo
EOF
write src/shop/Greeter.java <<'EOF'
package shop;

public class Greeter {
    public static String greet(String name) {
        return "Witaj, " + name + "!";
    }
}
EOF
commit "Add Polish messages and greeter"

git checkout -q -b feature/translations
as_student
write resources/messages_pl.properties <<'EOF'
# Generated by TransTool. Do not edit by hand: changes are overwritten by the next export.
cart.empty=Twój koszyk jest pusty
cart.total=Razem do zapłaty
checkout.pay=Zapłać
checkout.thanks=Dziękujemy za zakupy!
greeting=Dzień dobry
greeting.informal=Cześć
login.failed=Nieprawidłowy login lub hasło
login.locked=Konto zablokowane, spróbuj za 15 minut
EOF
commit "Update Polish translations (TransTool export 2026-01-02)"
state_set translations_blob "$(git rev-parse HEAD:resources/messages_pl.properties)"
write src/shop/Greeter.java <<'EOF'
package shop;

public class Greeter {
    public static String greet(String name) {
        return "Dzień dobry, " + name + "!";
    }
}
EOF
commit "Use formal greeting"
state_set feature_old_tip "$(git rev-parse HEAD)"

git checkout -q main
as "Piotr Zielinski" pzielinski
write resources/messages_pl.properties <<'EOF'
# Generated by TransTool. Do not edit by hand: changes are overwritten by the next export.
cart.empty=Twoj koszyk jest pusty
cart.total=Razem
checkout.pay=Zaplac
checkout.thanks=Dziekujemy za zakupy
greeting=Witaj
login.failed=Nieprawidlowy login lub haslo.
login.locked=Konto zablokowane
EOF
commit "Hotfix: add login.locked message"
write src/shop/Greeter.java <<'EOF'
package shop;

public class Greeter {
    public static String greet(String name) {
        return "Witaj, " + name.trim() + "!";
    }
}
EOF
commit "Trim user name in greeting"
state_set main_start "$(git rev-parse HEAD)"
git checkout -q feature/translations

setup_done
